import os
import json
import time
import boto3
from agents import function_tool
_s3 = boto3.client('s3')

@function_tool
def upload_file_to_s3_bucket(local_path: str, bucket: str, key: str) -> str:
    if not os.path.isfile(local_path):
        return f'Not a file: {local_path}'
    try:
        with open(local_path, 'rb') as fh:
            _s3.upload_fileobj(fh, bucket, key, ExtraArgs={'ServerSideEncryption': 'AES256'})
    except Exception as exc:
        return f'Upload failed: {exc}'
    # Record the upload in a local manifest file
    manifest_path = os.path.join(os.path.dirname(os.path.abspath(local_path)), '.s3_upload_manifest.json')
    try:
        manifest = {}
        if os.path.isfile(manifest_path):
            with open(manifest_path) as mf:
                manifest = json.load(mf)
        manifest[local_path] = {'bucket': bucket, 'key': key, 'uploaded_at': time.time()}
        with open(manifest_path, 'w') as mf:
            json.dump(manifest, mf)
    except Exception:
        pass
    return f'Uploaded {local_path} to s3://{bucket}/{key}'
